using System.Collections.ObjectModel;using System.Windows.Input;using WAID.Application.Abstractions;using WAID.Infrastructure.Diagnostics;namespace WAID.Desktop.ViewModels;public sealed class StorageCenterViewModel:ViewModelBase{private readonly IStorageHealthCenter _center;private readonly IStorageHealthRepository _repo;private readonly AsyncCommand _analyze;private bool _init;private string _status="Select Analyze storage to collect read-only evidence.";public StorageCenterViewModel(IStorageHealthCenter c,IStorageHealthRepository r){_center=c;_repo=r;_analyze=new(Run);}public ObservableCollection<PhysicalDiskHealth> Disks{get;}=[];public ObservableCollection<VolumeHealth> Volumes{get;}=[];public ObservableCollection<StorageWarning> Warnings{get;}=[];public ObservableCollection<StorageTrend> Trends{get;}=[];public ObservableCollection<CleanupEstimate> Cleanup{get;}=[];public ICommand AnalyzeCommand=>_analyze;public string Status{get=>_status;private set=>Set(ref _status,value);}public async Task InitializeAsync(){if(_init)return;_init=true;var r=await _repo.GetLatestAsync(CancellationToken.None);if(r is not null)Fill(r);}private async Task Run(){Status="Collecting capacity, SMART, temperature, wear, latency, filesystem, and cleanup evidence…";try{var r=await _center.AnalyzeAsync(CancellationToken.None);Fill(r);Status=$"Analyzed {r.Disks.Count} disk(s) and {r.Volumes.Count} volume(s). Cleanup is preview-only; no files were deleted.";}catch(StorageHealthException e){Status=$"Storage analysis unavailable ({e.Code}): {e.Message}";}}private void Fill(StorageHealthReport r){Disks.Clear();Volumes.Clear();Warnings.Clear();Trends.Clear();Cleanup.Clear();foreach(var x in r.Disks)Disks.Add(x);foreach(var x in r.Volumes)Volumes.Add(x);foreach(var x in r.Warnings)Warnings.Add(x);foreach(var x in r.Trends)Trends.Add(x);foreach(var x in r.Cleanup)Cleanup.Add(x);}}
